import sys, json
seen={}
for line in sys.stdin:
    line=line.strip()
    if not line: continue
    try: d=json.loads(line)
    except: continue
    for n in d.get('data',{}).get('searchProjects',{}).get('nodes',[]) or []:
        seen[n['id']]=n['name']
print(len(seen))
for i,n in sorted(seen.items(), key=lambda x:x[1]): print(i,n)
"

